const fetchSitePageTitle = async () => {
    try {
        let web = new Web(ContextValue.siteUrl);
        let sitePagesListId = ContextValue.SitePagesList || SelectedProp?.SelectedProp?.SitePagesList;
        // If SitePagesList ID is not available, get it by title
        if (!sitePagesListId) {
            try {
                const sitePagesList = await web.lists.getByTitle("Site Pages").get();
                sitePagesListId = sitePagesList.Id;
            } catch (error) {
                devError(error, "Error getting Site Pages list");
                setToolName("Team-Portfolio");
            }
        }
        // Fetch the page by FileLeafRef
        const pageItems = await web.lists.getById(sitePagesListId).items.select("ID", "FileLeafRef", "Page_x002d_Title", "Title").filter("FileLeafRef eq 'Team-Portfolio.aspx'").get();
        if (pageItems && pageItems.length > 0) {
            // Return Page_x002d_Title if available, otherwise Title
            setToolName(pageItems[0].Title || pageItems[0].Page_x002d_Title || "Team-Portfolio");
        } else {
            setToolName("Team-Portfolio");
        }
    } catch (error) {
        devError(error, "Error fetching SitePage title");
        setToolName("Team-Portfolio");
    }
}

const GetSmartmetadata = async () => {
    let siteConfigSites: any = [];
    var Priority: any = [];
    let Categories: any = [];
    let smartmetaDetails: any = [];
    // Was an inline SmartMetadata read:
    //   await new Web(siteUrl).lists.getById(ContextValue.SmartMetadataListID)
    //     .items.select(...).top(4999).expand("Parent").get();
    // Identical columns/expand — now shared. Safe to cache even though the
    // loop below writes `DataLoadNew` onto the rows: the cache clones on
    // the way out, so the stored copy is never touched.
    smartmetaDetails = await globalCommon.cachedListRead({
        siteUrl: ContextValue.siteUrl,
        listId: ContextValue.SmartMetadataListID,
        select: ["Id", "Title", "IsVisible", "ParentID", "SmartSuggestions", "TaxType", "Configurations", "Item_x005F_x0020_Cover", "listId", "siteName", "siteUrl", "SortOrder", "SmartFilters", "Selectable", 'Color_x0020_Tag', "Parent/Id", "Parent/Title"],
        expand: ["Parent"],
        top: 4999
    });
    setAllClientCategory(smartmetaDetails?.filter((metadata: any) => metadata?.TaxType == 'Client Category'));
    smartmetaDetails?.map((newtest: any) => {
        if (newtest.Title == "SDC Sites" || newtest.Title == "Shareweb Old" || newtest.Title == "Master Tasks")
            newtest.DataLoadNew = false;
        else if (newtest.TaxType == 'Sites' && newtest?.Title != "Master Tasks" && newtest?.Title != "SDC Sites" && newtest?.IsVisible == true && newtest?.listId != undefined) {
            siteConfigSites.push(newtest);
            siteConfigSites.sort((a: any, b: any) => {
                return a.SortOrder - b.SortOrder;
            });
            setsiteType(siteConfigSites);
        }
        if (newtest?.TaxType == 'Priority Rank') {
            Priority?.push(newtest)
        }
        if (newtest.TaxType == 'Categories') {
            Categories.push(newtest);
        }
    })
    if (siteConfigSites?.length > 0) {
        setSiteConfig(siteConfigSites);
    }
    setTaskCatagory(Categories);
    metaDataItem.push(...smartmetaDetails)
    setMetadata(smartmetaDetails);
};
